import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, EffectCoverflow } from "swiper/modules";
import "swiper/css";
import "swiper/css/effect-coverflow";

import img1 from "../../assets/17 New star.png";
import img2 from "../../assets/40 create party.png";
import img3 from "../../assets/46 click lock.png";
import img4 from "../../assets/14 gifting classic.png";
import img5 from "../../assets/11 live screen 1.png";
import img6 from "../../assets/10 Get started.png";
import img7 from "../../assets/34 Party event.png";
import img8 from "../../assets/81 expplore     all.png";
import img9 from "../../assets/live stream 2.png";
import img10 from "../../assets/stream feed 1.png";

const sliderData = [
  { img: img1, text: "Live Streaming Fun" },
  { img: img2, text: "Connect with Friends" },
  { img: img3, text: "Earn While You Stream" },
  { img: img4, text: "Join Interactive Games" },
  { img: img5, text: "Be Part of the Community" },
  { img: img6, text: "Win Exciting Rewards" },
  { img: img7, text: "Stream Anytime, Anywhere" },
  { img: img8, text: "Discover New Talents" },
  { img: img9, text: "Host Live Shows" },
  { img: img10, text: "Share Your Moments" },
];

export default function Front() {
  return (
    <section className="z-10 py-16 bg-black">
      <Swiper
        modules={[Autoplay, EffectCoverflow]}
        effect="coverflow"
        grabCursor={true}
        centeredSlides={true}
        slidesPerView={"auto"}
        loop={true}
        autoplay={{ delay: 2000, disableOnInteraction: false }}
        coverflowEffect={{
          rotate: 0,
          stretch: 0,
          depth: 150,
          modifier: 1.5,
          slideShadows: false,
        }}
        className="w-full max-w-[100%]"
      >
        {sliderData.map((slide, index) => (
          <SwiperSlide key={index} className="swiper-slide-custom relative">
            {/* Image with blur */}
            <img
              src={slide.img}
              alt={slide.text}
              className="w-full h-full object-cover rounded-3xl blur-[2px]"
            />

            {/* Dark overlay */}
            <div className="absolute inset-0 rounded-3xl bg-black/40"></div>

            {/* Centered Text */}
            <div className="absolute inset-0 flex items-center justify-center px-6">
              <h2 className="text-white text-3xl md:text-5xl font-bold text-center drop-shadow-lg">
                {slide.text}
              </h2>
            </div>
          </SwiperSlide>
        ))}
      </Swiper>

      <style>{`
        /* Base Slide */
        .swiper-slide-custom {
          width: 280px;
          height: 400px;
          transition: all 0.4s ease;
          transform: scale(0.8);
          opacity: 0.5;
        }

        /* Active Slide */
        .swiper-slide-active {
          width: 100% !important;
          height: 70vh !important;
          transform: scale(1);
          opacity: 1;
          box-shadow: 0 20px 40px rgba(0,0,0,0.4);
        }

        /* Make sure images fill */
        .swiper-slide-active img {
          width: 100%;
          height: 100%;
          object-fit: cover;
          border-radius: 1.5rem;
        }
      `}</style>
    </section>
  );
}
